def _contains_forbidden_apis_import(code):
    """Return True if code contains a disallowed ``apis`` import.

    The check is AST-based so it does not match string literals, comments, or
    docstrings.  Execution is intentionally pass-through: this only annotates
    the shell response, it never rewrites the submitted code.
