    try:
        tree = ast.parse(code)
    except SyntaxError:
        return False

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            if any(alias.name == 'apis' for alias in node.names):
                return True
        elif isinstance(node, ast.ImportFrom):
            if node.module == 'apis' and node.level == 0:
                return True
    return False


