import ast
import asyncio
import json
from pathlib import Path
import sys


_FORBIDDEN_IMPORT_MARKER = "Usage of the following module is not allowed: apis"
_APIS_IMPORT_HINT = ("Note: `apis` is already imported in this AppWorld shell; "
                     "do not use `import apis` or `from apis import ...`.")


async def _request(code):
    """Send one execution request to the persistent AppWorld shell."""
    socket = json.loads(Path('appworld-connection.json').read_text())['socket']
    reader, writer = await asyncio.open_unix_connection(socket, limit=8 * 1024 * 1024)
    try:
        writer.write((json.dumps({'operation': 'execute', 'code': code}) + '\n').encode())
        await writer.drain()
        return (await reader.readline()).decode().strip()
    finally:
        writer.close()
        await writer.wait_closed()


def _forbidden_apis_import_error(output):
    """Return True only for an execution failure caused by importing apis."""
    try:
        data = json.loads(output)
    except Exception:
        data = {'output': output, 'task_completed': False}
    if not isinstance(data, dict) or data.get('task_completed') is not False:
        return False
    return _FORBIDDEN_IMPORT_MARKER in str(data.get('output', ''))


def _with_apis_hint(output):
    """Append a recovery hint to a failed import-apis result."""
    try:
        data = json.loads(output)
        if isinstance(data, dict):
            data = dict(data)
            data['output'] = str(data.get('output', '')) + '\n' + _APIS_IMPORT_HINT
            return json.dumps(data)
    except Exception:
        pass
    return output + '\n' + _APIS_IMPORT_HINT


def _is_apis_import(node):
    if isinstance(node, ast.Import):
        return any(alias.name == 'apis' or alias.name.startswith('apis.')
                   for alias in node.names)
    if isinstance(node, ast.ImportFrom):
        return node.module is not None and (node.module == 'apis' or node.module.startswith('apis.'))
    return False


def _import_replacement(node):
    """Return a source-level replacement for one top-level apis import statement."""
    parts = []
    if isinstance(node, ast.Import):
        kept = []
        for alias in node.names:
            if alias.name == 'apis' or alias.name.startswith('apis.'):
                if alias.asname:
                    target = alias.name
                    parts.append(f"{alias.asname} = {target}")
                else:
                    # `apis` itself is already injected into the shell namespace.
                    parts.append('pass')
            else:
                kept.append(alias.name + (f' as {alias.asname}' if alias.asname else ''))
        if kept:
            parts.insert(0, 'import ' + ', '.join(kept))
    elif isinstance(node, ast.ImportFrom):
        assignments = []
        for alias in node.names:
            if alias.name == '*':
                assignments.append(
                    "globals().update({k: getattr(apis, k) for k in dir(apis) "
                    "if not k.startswith('_')})"
                )
            else:
                target = f"{node.module}.{alias.name}" if node.module != 'apis' else f"apis.{alias.name}"
                assignments.append(f"{alias.asname or alias.name} = {target}")
        parts.extend(assignments)
    return '; '.join(part for part in parts if part)


def _node_offsets(code, node):
    lines = code.splitlines(keepends=True)
    start = sum(len(line) for line in lines[:node.lineno - 1]) + node.col_offset
    end = sum(len(line) for line in lines[:node.end_lineno - 1]) + node.end_col_offset
    return start, end


def _replace_nodes(code, replacements):
    for start, end, replacement in sorted(replacements, key=lambda item: item[0], reverse=True):
        code = code[:start] + replacement + code[end:]
    return code


def _leading_apis_import_correction(code):
    """Correct a top-level leading `import apis` / `from apis import ...`.

    Returns corrected source only when the forbidden import is in the leading
    run of import statements, so retrying cannot duplicate a prior state-changing
    call from the original snippet.
    """
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return None

    leading = []
    for node in tree.body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            leading.append(node)
        elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) \
                and isinstance(node.value.value, str):
            leading.append(node)  # module docstring
        else:
            break

    offending = [node for node in leading if _is_apis_import(node)]
    if not offending:
        return None

    replacements = []
    for node in offending:
        start, end = _node_offsets(code, node)
        replacements.append((start, end, _import_replacement(node)))
    return _replace_nodes(code, replacements)


async def execute(code):
    output = await _request(code)
    if _forbidden_apis_import_error(output):
        corrected = _leading_apis_import_correction(code)
        if corrected is not None and corrected != code:
            try:
                output = await _request(corrected)
            except Exception:
                output = _with_apis_hint(output)
        else:
            output = _with_apis_hint(output)
    return output


