    def __init__(self):
        self.changed = False

    def visit_Import(self, node):
        normal_names = []
        apis_aliases = []
        for alias in node.names:
            if alias.name == 'apis':
                self.changed = True
                apis_aliases.append(alias.asname)
            else:
                normal_names.append(alias)

        statements = []
        if normal_names:
            statements.append(ast.Import(names=normal_names))
        for alias in apis_aliases:
            if alias:
