def _rewrite_apis_imports(code):
    """Rewrite ``import apis`` / ``from apis import ...`` to use the preloaded
    ``apis`` object.

    AppWorld injects ``apis`` as a builtin and its secure importer rejects
    ``import apis``, so those statements always raise.  Rewriting them before
    they reach the shell converts a guaranteed traceback into working code.
    Only ``apis`` imports are touched; everything else is left byte-for-byte
    identical.
