                for alias in node.names:
                    if alias.name == "*":
                        continue
                    target = alias.asname or alias.name
                    replacements.append(f"{target} = {module}.{alias.name}")
                edits.append((node, "\n".join(replacements) if replacements else "pass"))

    if not edits:
        return code

    line_offsets = [0]
    for line in code.splitlines(keepends=True):
        line_offsets.append(line_offsets[-1] + len(line.encode("utf-8")))
    code_bytes = bytearray(code.encode("utf-8"))

    prepared = []
    for node, replacement in edits:
        start_line = node.lineno
