        start = line_offsets[start_line - 1] + node.col_offset
        end = line_offsets[end_line - 1] + getattr(node, "end_col_offset", 0)
        indent = code_bytes[line_offsets[start_line - 1]:start]
        prepared.append((start, end, indent, replacement))

    # Apply from the bottom up so earlier byte offsets remain valid.
    for start, end, indent, replacement in sorted(prepared, key=lambda item: item[0], reverse=True):
        replacement_bytes = replacement.encode("utf-8")
        if "\n" in replacement:
            first, *rest = replacement.split("\n")
