    return name == 'apis' or name.startswith('apis.')


def _alias_text(alias):
    if alias.asname:
        return f"{alias.name} as {alias.asname}"
    return alias.name


def _node_offsets(code, node):
    """Return (start, end) character offsets for an AST node.

    ``ast`` reports ``col_offset``/``end_col_offset`` as UTF-8 byte offsets,
    so map through the UTF-8 encoding rather than slicing by character count.
    """
    lines = code.splitlines(keepends=True)
    line_start_bytes = [0]
    for line in lines:
        line_start_bytes.append(line_start_bytes[-1] + len(line.encode('utf-8')))
    start_byte = line_start_bytes[node.lineno - 1] + node.col_offset
    end_byte = line_start_bytes[node.end_lineno - 1] + node.end_col_offset
    encoded = code.encode('utf-8')
    start = len(encoded[:start_byte].decode('utf-8'))
    end = len(encoded[:end_byte].decode('utf-8'))
    return start, end


