    """Build replacement source for ``import ...`` statements touching apis.

    The preloaded ``apis`` object is already bound in the AppWorld shell, so
    ``import apis`` has no effect and ``import apis as x`` becomes ``x = apis``.
    Non-apis aliases in the same statement are preserved as a normal import.
    """
    parts = []
    safe_aliases = []
    for alias in node.names:
        if _is_apis_module_name(alias.name):
            if alias.name == 'apis':
                if alias.asname:
                    parts.append(f"{alias.asname} = apis")
            else:
