                # available; only an explicit alias needs a local binding.
                if alias.asname:
                    parts.append(f"{alias.asname} = {alias.name}")
        else:
            safe_aliases.append(_alias_text(alias))
    if safe_aliases:
        parts.append('import ' + ', '.join(safe_aliases))
    return '; '.join(parts)


