    leading_fixes = []
    for stmt in tree.body:
        if _is_bare_apis_import(stmt):
            leading_fixes.append(stmt)
        elif _is_harmless_leading(stmt):
            continue
        else:
            break

    if not leading_fixes:
        return None

    # A statement can only be spliced safely if it occupies a single source
    # line. Multiple fixes on the same line are ambiguous; leave them alone.
    if any(stmt.end_lineno != stmt.lineno for stmt in leading_fixes):
        return None
    if len({stmt.lineno for stmt in leading_fixes}) != len(leading_fixes):
        return None

    fixed_ids = {id(stmt) for stmt in leading_fixes}
    if any(
        _is_apis_import_node(node) and id(node) not in fixed_ids
        for node in ast.walk(tree)
    ):
        # There is another forbidden `apis` import (a mixed/nested import or a
        # `from apis import ...`) that would still fail after our splice. Do not
        # run a partially corrected program; let the caller surface the hint.
        return None

    lines = code.splitlines(keepends=True)
    for stmt in sorted(leading_fixes, key=lambda s: (s.lineno, s.col_offset), reverse=True):
        line = lines[stmt.lineno - 1]
        replacement = _replacement_for_apis_import(stmt)
        lines[stmt.lineno - 1] = (
            line[:stmt.col_offset] + replacement + line[stmt.end_col_offset:]
        )
    return ''.join(lines)


def maybe_recover_apis_import(code, raw_output):
    if FORBIDDEN_APIS_ERROR not in raw_output:
        return raw_output, False
    corrected = recover_bare_apis_import(code)
    if corrected is None:
        return raw_output + '\n' + FORBIDDEN_APIS_HINT, False
    return corrected, True


def main():
    for line in sys.stdin:
        request = json.loads(line)
        if 'id' not in request:
            continue
        method = request['method']
        try:
            if method == 'initialize':
                result = {'protocolVersion': request['params']['protocolVersion'],
                          'capabilities': {'tools': {}},
                          'serverInfo': {'name': 'appworld', 'version': '1.0.0'}}
            elif method == 'ping':
                result = {}
            elif method == 'tools/list':
                result = {'tools': [{'name': 'appworld_execute',
                          'description': 'Execute Python in the supplied persistent AppWorld shell. The `apis` module is already preloaded (do not import it); print outputs and discover app APIs through `apis.api_docs`.',
                          'inputSchema': {'type': 'object', 'properties': {'code': {'type': 'string'}}, 'required': ['code'], 'additionalProperties': False}}]}
            elif method == 'tools/call':
                if request['params']['name'] != 'appworld_execute':
                    raise ValueError('Unknown tool')
                code = request['params']['arguments']['code']
                raw_output = asyncio.run(execute(code))
                recovered, was_corrected = maybe_recover_apis_import(code, raw_output)
                if was_corrected:
                    raw_output = asyncio.run(execute(recovered))
                    if FORBIDDEN_APIS_ERROR in raw_output:
                        raw_output += '\n' + FORBIDDEN_APIS_HINT
                result = {'content': [{'type': 'text', 'text': raw_output}]}
            else:
                print(json.dumps({'jsonrpc': '2.0', 'id': request['id'], 'error': {'code': -32601, 'message': 'Method not found'}}), flush=True)
                continue
        except Exception as error:
            result = {'content': [{'type': 'text', 'text': str(error)}], 'isError': True}
        print(json.dumps({'jsonrpc': '2.0', 'id': request['id'], 'result': result}), flush=True)


if __name__ == '__main__':
    main()
